void Object::compact() {
  if (M.empty())
    return;
  Storage Packed(M.size());
  if (Packed.getMemorySize() >= M.getMemorySize())
    return;
  for (auto &KV : M)
    Packed.try_emplace(std::move(KV.first), std::move(KV.second));
  M = std::move(Packed);
}

